mapper.select:
SELECT r.*, g.goods_name, w.warehouse_name, u.real_name as operator_name
FROM biz_stock_record r
INNER JOIN biz_goods g ON r.goods_id = g.id
INNER JOIN biz_warehouse w ON r.warehouse_id = w.id
LEFT JOIN sys_user u ON r.operator_id = u.id
WHERE 1=1

    AND r.goods_id = #{goodsId}


    AND r.warehouse_id = #{warehouseId}


    AND r.record_type = #{recordType}

ORDER BY r.create_time DESC
